// reference matcher: returns params or nil
func refMatch(pat, path string) map[string]string {
	if pat == "" {
		if path == "" {
			return map[string]string{}
		}
		return nil
	}
	if pat[0] == '*' {
		return map[string]string{"*": path}
	}
	if pat[0] == ':' {
		i := 1
		for i < len(pat) && pat[i] != '/' {
			i++
		}
		name := pat[1:i]
		rest := pat[i:]
		j := 0
		for j < len(path) && path[j] != '/' {
			j++
		}
		if j == 0 {
			return nil
		}
		p := refMatch(rest, path[j:])
		if p == nil {
			return nil
		}
		p[name] = path[:j]
		return p
	}
	i := 0
	for i < len(pat) && pat[i] != ':' && pat[i] != '*' {
		i++
	}
	seg := pat[:i]
	if !strings.HasPrefix(path, seg) {
		return nil
	}
	return refMatch(pat[i:], path[i:])
}

// priority: compare two matching patterns; lower is better (static < param < any)
func kindAt(pat string, pos int) int {
	// pos is index into pattern; determine kind of the token starting at pos
	if pos >= len(pat) {
		return -1
	}
	switch pat[pos] {
	case ':':
		return 1
	case '*':
		return 2
	default:
		return 0
	}
}

func better(a, b string) bool {
	// true if a has higher priority than b
	i := 0
	for i < len(a) && i < len(b) {
		ka, kb := kindAt(a, i), kindAt(b, i)
		if ka != kb {
			return ka < kb
		}
		if ka == 0 {
			if a[i] != b[i] {
				return false // both static but different char: can't both match
			}
			i++
			continue
		}
		// same kind param/any: skip token
		if ka == 1 {
			for i < len(a) && a[i] != '/' {
				i++
			}
		} else {
			i = len(a)
		}
	}
	return len(a) >= len(b)
}

func refBest(patterns []string, path string) (string, map[string]string) {
	var matches []string
	for _, p := range patterns {
		if refMatch(p, path) != nil {
			matches = append(matches, p)
		}
	}
	if len(matches) == 0 {
		return "", nil
	}
	sort.SliceStable(matches, func(i, j int) bool { return better(matches[i], matches[j]) })
	return matches[0], refMatch(matches[0], path)
}

