		return map[string]string{"*": path}
	}
	if pat[0] == ':' {
		i := 1
		for i < len(pat) && pat[i] != '/' {
			i++
		}
		name := pat[1:i]
		rest := pat[i:]
		j := 0
		for j < len(path) && path[j] != '/' {
			j++
		}
		if j == 0 {
			return nil
		}
		p := refMatch2(rest, path[j:])
		if p == nil {
			return nil
		}
		p[name] = path[:j]
		return p
	}
	i := 0
	for i < len(pat) && pat[i] != ':' && pat[i] != '*' {
		i++
	}
	seg := pat[:i]
	if !strings.HasPrefix(path, seg) {
		return nil
	}
	return refMatch2(pat[i:], path[i:])
}

func kindAt2(pat string, pos int) int {
	if pos >= len(pat) {
		return -1
	}
	switch pat[pos] {
	case ':':
		return 1
	case '*':
		return 2
	default:
		return 0
	}
}

func better2(a, b string) bool {
	i := 0
	for i < len(a) && i < len(b) {
		ka, kb := kindAt2(a, i), kindAt2(b, i)
		if ka != kb {
			return ka < kb
		}
		if ka == 0 {
			if a[i] != b[i] {
				return false
			}
			i++
			continue
		}
		if ka == 1 {
			for i < len(a) && a[i] != '/' {
				i++
			}
		} else {
			i = len(a)
		}
	}
	return len(a) <= len(b)
}

func refBest2(patterns []string, path string) (string, map[string]string) {
	var matches []string
	for _, p := range patterns {
		if refMatch2(p, path) != nil {
			matches = append(matches, p)
		}
	}
	if len(matches) == 0 {
		return "", nil
	}
	sort.SliceStable(matches, func(i, j int) bool { return better2(matches[i], matches[j]) })
	return matches[0], refMatch2(matches[0], path)
}

