// isHTTPScheme reports whether the given value is a valid HTTP protocol scheme,
// i.e. `http` or `https`. Any other value (for example a value injected through
// a forwarded header) is not a scheme and must be ignored.
func isHTTPScheme(scheme string) bool {
	return strings.EqualFold(scheme, "http") || strings.EqualFold(scheme, "https")
}

